const linhas = $input.all().map(i => i.json).filter(l => l.status);

// Aceita número (1332.64) ou texto ("1.332,64")
const num = v => {
  if (typeof v === 'number') return v;
  let s = String(v ?? '').replace(/[^\d.,-]/g, '');
  if (s.includes(',')) s = s.replace(/\./g, '').replace(',', '.');
  return Number(s) || 0;
};

const soma = (obj, chave, valor) => {
  obj[chave] = Number(((obj[chave] || 0) + valor).toFixed(2));
};

const concluidas = linhas.filter(l => l.status === 'Concluída');

const porCategoria = {};
const porResponsavel = {};
const porStatus = {};

for (const l of linhas) {
  porStatus[l.status] = (porStatus[l.status] || 0) + 1;
}
for (const l of concluidas) {
  soma(porCategoria, l.categoria, num(l.valor));
  soma(porResponsavel, l.responsavel, num(l.valor));
}

const total = concluidas.reduce((s, l) => s + num(l.valor), 0);

return [{
  json: {
    totalRegistros: linhas.length,
    totalConcluido: Number(total.toFixed(2)),
    qtdConcluidas: concluidas.length,
    porStatus,
    porCategoria,
    porResponsavel
  }
}];

const resumo = $('Tratar dados').first().json;
const texto = ($input.first().json.text || '')
  .replace(/```html|```/g, '')
  .trim();

const brl = v => Number(v).toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });
const hoje = new Date().toLocaleDateString('pt-BR', { timeZone: 'America/Recife' });

const td = 'padding:6px 12px;border:1px solid #ccc';
const th = 'padding:6px 12px;border:1px solid #ccc;background:#1F4E78;color:#fff;text-align:left';

const tabelaValores = (titulo, obj) => {
  const linhas = Object.entries(obj)
    .sort((a, b) => b[1] - a[1])
    .map(([k, v]) => `<tr><td style="${td}">${k}</td><td style="${td};text-align:right">${brl(v)}</td></tr>`)
    .join('');
  return `<h3>${titulo}</h3>
<table style="border-collapse:collapse;font-size:14px">
<tr><th style="${th}">Nome</th><th style="${th}">Total concluído</th></tr>${linhas}</table>`;
};

const linhasStatus = Object.entries(resumo.porStatus)
  .map(([k, v]) => `<tr><td style="${td}">${k}</td><td style="${td};text-align:right">${v}</td></tr>`)
  .join('');

const html = `
<div style="font-family:Arial,sans-serif;max-width:640px;color:#222">
<h2>Relatório de vendas - ${hoje}</h2>
${texto}
<hr>
<h3>Números do período</h3>
<p><b>Total concluído:</b> ${brl(resumo.totalConcluido)} em ${resumo.qtdConcluidas} vendas
(de ${resumo.totalRegistros} registros)</p>
${tabelaValores('Por categoria', resumo.porCategoria)}
${tabelaValores('Por responsável', resumo.porResponsavel)}
<h3>Por status</h3>
<table style="border-collapse:collapse;font-size:14px">
<tr><th style="${th}">Status</th><th style="${th}">Quantidade</th></tr>${linhasStatus}</table>
<p style="font-size:12px;color:#777">Relatório gerado automaticamente com n8n e IA.</p>
</div>`;

return [{ json: { html, assunto: `Relatório de vendas - ${hoje}` } }];
